/* @lc app=leetcode id=3651 lang=kotlin */ class Solution { fun layer(g: Array<IntArray>, prev: Array<IntArray>?): Array<IntArray> = IntArray(10002) { 1_000_000_000 }.also { suf -> prev?.let { p -> g.indices.forEach { i -> g[0].indices.forEach { j -> suf.set(g[i][j], minOf(suf[g[i][j]], p[i][j])) } } } }.also { suf -> (10000 downTo 0).forEach { v -> suf[v] = minOf(suf[v], suf[v + 1]) } }.let { suf -> Array(g.size) { IntArray(g[0].size) { 1_000_000_000 } }.also { cur -> g.indices.forEach { i -> g[0].indices.forEach { j -> cur[i][j] = minOf(if (prev == null) 1_000_000_000 else suf[g[i][j]], if (i == 0 && j == 0) 0 else minOf(if (i > 0) cur[i - 1][j] else 1_000_000_000, if (j > 0) cur[i][j - 1] else 1_000_000_000) + g[i][j]) } } } } fun minCost(grid: Array<IntArray>, k: Int): Int = (1..k).runningFold(layer(grid, null)) { prev, _ -> layer(grid, prev) }.minOf { it[grid.size - 1][grid[0].size - 1] } }